import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { PAGE_CSS } from "./serve.js";
import { cn, SIGNAL_THEME } from "./browser/components/ui/utils.js";

/** The console's two hand-written stylesheets: the server pages' CSS in
 * serve.ts and the React workspace's CSS. */
const WORKSPACE_CSS = readFileSync(new URL("./browser/workspace.css", import.meta.url), "utf8");
const SHEETS = { "serve.ts page CSS": PAGE_CSS, "workspace.css": WORKSPACE_CSS };
/** Signal's tokens, generated by youi; the server prepends them to its page CSS. */
const TOKENS_CSS = readFileSync(new URL("./design/tokens.css", import.meta.url), "utf8");

type Rule = { selectors: string[]; body: string; at: string[] };

/** Every style rule with its selectors, declarations and enclosing at-rules. */
function rulesOf(css: string): Rule[] {
  const text = css.replace(/\/\*[\s\S]*?\*\//g, "");
  const rules: Rule[] = [];
  const walk = (from: number, to: number, at: string[]): void => {
    let start = from;
    for (let i = from; i < to; i++) {
      if (text[i] === ";") { start = i + 1; continue; }
      if (text[i] !== "{") continue;
      let depth = 1, j = i + 1;
      for (; depth > 0; j++) {
        if (text[j] === "{") depth++;
        else if (text[j] === "}") depth--;
      }
      const prelude = text.slice(start, i).trim();
      if (prelude.startsWith("@")) walk(i + 1, j - 1, [...at, prelude]);
      else rules.push({ selectors: splitSelectors(prelude), body: text.slice(i + 1, j - 1), at });
      i = j - 1;
      start = j;
    }
  };
  walk(0, text.length, []);
  return rules;
}

function splitSelectors(prelude: string): string[] {
  const out: string[] = [];
  let depth = 0, current = "";
  for (const ch of prelude) {
    if (ch === "(" || ch === "[") depth++;
    if (ch === ")" || ch === "]") depth--;
    if (ch === "," && depth === 0) { out.push(current.trim()); current = ""; } else current += ch;
  }
  out.push(current.trim());
  return out;
}

const finePointer = (at: string) => /^@media\b/.test(at) && /hover:\s*hover/.test(at) && /pointer:\s*fine/.test(at);

describe("console feel: touch, hover and press", () => {
  test("every :hover rule sits inside (hover: hover) and (pointer: fine)", () => {
    for (const [name, css] of Object.entries(SHEETS)) {
      const hovers = rulesOf(css).filter(rule => rule.selectors.some(s => s.includes(":hover")));
      expect(hovers.length, name).toBeGreaterThan(10);
      const stuck = hovers.filter(rule => !rule.at.some(finePointer)).map(rule => rule.selectors.join(", "));
      expect(stuck, name).toEqual([]);
    }
  });
});

describe("Signal tokens: one generated source", () => {
  /** The workspace stylesheet the server delivers: workspace.css with the compiled Tailwind utilities appended. */
  const BUILT_CSS = readFileSync(new URL("../dist/browser/workspace.css", import.meta.url), "utf8");
  const customProperties = (css: string) => rulesOf(css).flatMap(rule => rule.body.split(";"))
    .map(declaration => declaration.match(/^\s*(--so-[\w-]+)\s*:\s*(.*?)\s*$/s))
    .filter(match => match !== null).map(match => ({ name: match[1]!, value: match[2]! }));
  const generated = new Set(customProperties(TOKENS_CSS).map(property => property.name));

  test("cn knows Signal's type, radius and shadow names, so a later colour never drops a role", () => {
    const theme = readFileSync(new URL("./design/theme.css", import.meta.url), "utf8");
    const names = (prefix: string) => [...theme.matchAll(new RegExp(`--${prefix}-([\\w-]+?): `, "g"))].map(match => match[1]!).filter(name => !name.includes("--"));
    expect([...SIGNAL_THEME.text].sort()).toEqual(names("text").sort());
    expect([...SIGNAL_THEME.radius].sort()).toEqual(names("radius").filter(name => !["sm", "md", "lg", "xl"].includes(name)).sort());
    expect([...SIGNAL_THEME.shadow].sort()).toEqual(names("shadow").sort());
    expect(cn("text-caption", "text-muted-foreground")).toBe("text-caption text-muted-foreground");
    expect(cn("text-body", "text-caption")).toBe("text-caption");
    expect(cn("rounded-card", "rounded-md")).toBe("rounded-md");
  });

  test("the workspace sheet only reads the generated tokens, so it never overrides a person's accent", () => {
    const declared = customProperties(BUILT_CSS);
    expect(declared.length).toBeGreaterThan(0);
    for (const { name, value } of declared) {
      expect(generated.has(name), name).toBe(false);
      expect(value, name).toMatch(/^var\(/);
    }
  });
});
